scripts.script:
const effTemplate = thisItem.effects.getName("粉蝶");
if (effTemplate) {
    const effData = effTemplate.toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effData);
}

const fendie = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_fendie");
const currentStacks = fendie ? (fendie.getFlag("xjzl-system", "stacks") || 1) : 0;
if (currentStacks > 0) {
    const htmlContent = `
        <div style="margin-bottom: 10px; color: #555;">
            <p>当前拥有 <b>${currentStacks}</b> 层 [粉蝶]。</p>
            <p style="color:#e67e22;">每消耗 1 层粉蝶，本次招式伤害 +10。</p>
        </div>
        <div class="form-group">
            <label style="font-weight:bold;">选择消耗层数 (0-${currentStacks}):</label>
            <input type="number" name="spendCount" value="0" min="0" max="${currentStacks}" style="text-align:center;">
        </div>
    `;
    const spendResult = await foundry.applications.api.DialogV2.prompt({
        window: { title: "蝶舞飘 - 粉蝶增伤", icon: "fas fa-fire" },
        content: htmlContent,
        ok: {
            label: "确认",
            icon: "fas fa-check",
            callback: (event, button) => { return parseInt(new FormData(button.form).get("spendCount")) || 0; }
        },
        rejectClose: false
    });
    if (spendResult && spendResult > 0) {
        const finalSpend = Math.min(spendResult, currentStacks);
        await game.xjzl.api.effects.removeEffect(actor, "wuxue_fendie", finalSpend);
        const bonus = finalSpend * 10;
        args.flags.damageResult.damage += bonus;
        args.flags.damageResult.breakdown += `\n+ 消耗 ${finalSpend} 层粉蝶: ${bonus}`;
        ui.notifications.info(`已消耗 ${finalSpend} 层粉蝶，招式伤害 +${bonus}！`);
    }
}

if (args.isHit) {
    const effTemplate = thisItem.effects.getName("粉蝶");
    if (effTemplate) {
        const effData = effTemplate.toObject();
        delete effData._id;
        effData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(attacker, effData);
    }
}

const fendie = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_fendie");
const currentStacks = fendie ? (fendie.getFlag("xjzl-system", "stacks") || 1) : 0;
if (currentStacks > 0) {
    const htmlContent = `
        <div style="margin-bottom: 10px; color: #555;">
            <p>当前拥有 <b>${currentStacks}</b> 层 [粉蝶]。</p>
            <p style="color:#e67e22;">每消耗 1 层粉蝶，本次招式伤害 +10。</p>
        </div>
        <div class="form-group">
            <label style="font-weight:bold;">选择消耗层数 (0-${currentStacks}):</label>
            <input type="number" name="spendCount" value="0" min="0" max="${currentStacks}" style="text-align:center;">
        </div>
    `;
    const spendResult = await foundry.applications.api.DialogV2.prompt({
        window: { title: "蝶舞飘 - 粉蝶增伤", icon: "fas fa-fire" },
        content: htmlContent,
        ok: {
            label: "确认",
            icon: "fas fa-check",
            callback: (event, button) => { return parseInt(new FormData(button.form).get("spendCount")) || 0; }
        },
        rejectClose: false
    });
    if (spendResult && spendResult > 0) {
        const finalSpend = Math.min(spendResult, currentStacks);
        await game.xjzl.api.effects.removeEffect(actor, "wuxue_fendie", finalSpend);
        const bonus = finalSpend * 10;
        args.flags.damageResult.damage += bonus;
        args.flags.damageResult.breakdown += `\n+ 消耗 ${finalSpend} 层粉蝶: ${bonus}`;
        ui.notifications.info(`已消耗 ${finalSpend} 层粉蝶，招式伤害 +${bonus}！`);
    }
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "root", duration: { rounds: 2 } });
    ui.notifications.info(`${args.target.name} 被禁足！`);
}
const effTemplate = thisItem.effects.getName("粉蝶");
if (effTemplate) {
    const effData = effTemplate.toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(attacker, effData, 2);
}

const fendie = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_fendie");
const currentStacks = fendie ? (fendie.getFlag("xjzl-system", "stacks") || 1) : 0;
if (currentStacks > 0) {
    const htmlContent = `
        <div style="margin-bottom: 10px; color: #555;">
            <p>当前拥有 <b>${currentStacks}</b> 层 [粉蝶]。</p>
            <p style="color:#e67e22;">每消耗 1 层粉蝶，本次招式伤害 +10。</p>
        </div>
        <div class="form-group">
            <label style="font-weight:bold;">选择消耗层数 (0-${currentStacks}):</label>
            <input type="number" name="spendCount" value="0" min="0" max="${currentStacks}" style="text-align:center;">
        </div>
    `;
    const spendResult = await foundry.applications.api.DialogV2.prompt({
        window: { title: "蝶舞飘 - 粉蝶增伤", icon: "fas fa-fire" },
        content: htmlContent,
        ok: {
            label: "确认",
            icon: "fas fa-check",
            callback: (event, button) => { return parseInt(new FormData(button.form).get("spendCount")) || 0; }
        },
        rejectClose: false
    });
    if (spendResult && spendResult > 0) {
        const finalSpend = Math.min(spendResult, currentStacks);
        await game.xjzl.api.effects.removeEffect(actor, "wuxue_fendie", finalSpend);
        const bonus = finalSpend * 10;
        args.flags.damageResult.damage += bonus;
        args.flags.damageResult.breakdown += `\n+ 消耗 ${finalSpend} 层粉蝶: ${bonus}`;
        ui.notifications.info(`已消耗 ${finalSpend} 层粉蝶，招式伤害 +${bonus}！`);
    }
}

const noStanceTargets = args.targets.filter(t => t.isHit && !t.target.system.martial.stanceActive);
if (noStanceTargets.length === 0) return;

const fendie = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_fendie");
const stacks = fendie ? (fendie.getFlag("xjzl-system", "stacks") || 1) : 0;

if (stacks >= 3) {
    const targetNames = noStanceTargets.map(t => t.target.name).join("、");
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "落花随舞" },
        content: `<p>命中无架招目标：<b>${targetNames}</b>。</p><p>是否消耗 3 层 [粉蝶] 迫使他们随你起舞？</p>`,
        yes: { label: "消耗" },
        no: { label: "跳过" }
    });

    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "wuxue_fendie", 3);

        for (const t of noStanceTargets) {
            const tActor = t.target;
            const actionFlags = tActor.getFlag("xjzl-system", "actions") || {};
            const hasReaction = actionFlags.reaction ?? true;

            if (hasReaction) {
                ChatMessage.create({
                    content: `<div class="xjzl-chat-card" style="margin-left:6px;">
                        <div style="border-left: 3px solid #e91e63; padding: 4px; background: rgba(233, 30, 99, 0.05);">
                            <div style="font-weight:bold; color:#e91e63;"><i class="fas fa-fan"></i> 粉蝶起舞</div>
                            <div>目标 <b>${tActor.name}</b> 动作可用。</div>
                            <div style="font-size:0.85em; color:#666; margin-top:3px;">请对方消耗反应动作随你起舞。</div>
                        </div>
                    </div>`,
                    speaker: ChatMessage.getSpeaker({actor: actor})
                });
            } else {
                ChatMessage.create({
                    content: `<div class="xjzl-chat-card" style="margin-left:6px;">
                        <div style="border-left: 3px solid #e91e63; padding: 4px; background: rgba(233, 30, 99, 0.05);">
                            <div style="font-weight:bold; color:#e91e63;"><i class="fas fa-fan"></i> 粉蝶起舞</div>
                            <div>目标 <b>${tActor.name}</b> 没有反应动作。</div>
                            <div style="font-size:0.85em; color:#c62828; margin-top:3px;">已自动流失其 <b>30</b> 点内力与 <b>3</b> 点怒气。</div>
                        </div>
                    </div>`,
                    speaker: ChatMessage.getSpeaker({actor: actor})
                });
                await tActor.applyHealing({ healer: actor,  amount: -30, type: "mp", showScrolling: true });
                const currentRage = tActor.system.resources.rage.value || 0;
                await tActor.update({ "system.resources.rage.value": Math.max(0, currentRage - 3) });
            }
        }
    }
}

if (!Macros.checkStance(actor, args)) return;
if (args.attacker) {
    const effTemplate = thisItem.effects.getName("飞花");
    if (effTemplate) {
        const effData = effTemplate.toObject();
        delete effData._id;
        effData.origin = thisItem.uuid;
        const lvl = Math.max(1, move.computedLevel || 1);
        await game.xjzl.api.effects.addEffect(args.attacker, effData, lvl);
        actor.showFloatyText("移花反震！", { fill: "#FFA500" });
    }
}

if (args.isHit) {
    const rawDamage = args.isCrit ? args.baseDamage * 2 : args.baseDamage;
    const splash = Math.floor(rawDamage / 2);
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="margin-left:6px;">
            <div style="border-left: 3px solid #9c27b0; padding: 4px; background: rgba(156, 39, 176, 0.05);">
                <div style="font-weight:bold; color:#9c27b0;"><i class="fas fa-fan"></i> 花须蝶芒 - 气劲溅射</div>
                <div>请手动对目标周围 2米 内其他敌人造成 <b>${splash}</b> 点气血流失。</div>
                <div style="font-size:0.85em; color:#666; margin-top:3px;">（此流失伤害不触发飞花效果）</div>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "fushen", duration: { rounds: 2 } });

    const feihua = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_feihua");
    if (feihua) {
        const stacks = feihua.getFlag("xjzl-system", "stacks") || 1;
        const extraDrain = 5 * stacks;
        await args.target.applyHealing({ healer: actor,  amount: -extraDrain, type: "mp", showScrolling: true });
        ChatMessage.create({
            content: `<div class="xjzl-chat-card" style="margin-left:6px;">
                <div style="border-left: 3px solid #e91e63; padding: 4px; background: rgba(233, 30, 99, 0.05);">
                    <div style="font-weight:bold; color:#e91e63;"><i class="fas fa-bolt"></i> 枯木生花 - 双倍飞花</div>
                    <div style="font-size:0.85em; margin-top:3px;">击破架招，飞花反噬加剧，额外流失 <b>${extraDrain}</b> 点内力。</div>
                </div>
            </div>`,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (args.isHit) {
    const rawDamage = args.isCrit ? args.baseDamage * 2 : args.baseDamage;
    const splash = Math.floor(rawDamage / 2);
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="margin-left:6px;">
            <div style="border-left: 3px solid #9c27b0; padding: 4px; background: rgba(156, 39, 176, 0.05);">
                <div style="font-weight:bold; color:#9c27b0;"><i class="fas fa-fan"></i> 玉树琼芝 - 气劲溅射</div>
                <div>请手动对目标周围 2米 内其他敌人造成 <b>${splash}</b> 点气血流失。</div>
                <div style="font-size:0.85em; color:#666; margin-top:3px;">（此流失伤害不触发飞花效果）</div>
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const effTemplate = thisItem.effects.getName("移花");
if (effTemplate) {
    const effData = effTemplate.toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    const lvl = Math.max(1, move.computedLevel || 1);
    effData.duration = { rounds: 2 + (lvl - 1) };
    foundry.utils.setProperty(effData, "flags.xjzl-system.yihuaLevel", lvl);
    await game.xjzl.api.effects.addEffect(actor, effData);
}

if (args.item && args.item.name === "移花掌法") {
    const stacks = thisEffect.getFlag("xjzl-system", "stacks") || 1;
    const drain = 5 * stacks;
    await actor.applyHealing({ healer: actor,  amount: -drain, type: "mp", showScrolling: true });
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="border-left: 3px solid #e91e63; padding: 4px; background: rgba(233, 30, 99, 0.05);"><div style="font-weight:bold; color:#e91e63;"><i class="fas fa-leaf"></i> 飞花反噬</div><div style="font-size:0.85em;">因移花掌法招式影响，内力流失 <b>${drain}</b> 点。</div></div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (['waigong', 'neigong'].includes(args.type)) {
    const rawDamage = args.isCrit ? args.baseDamage * 2 : args.baseDamage;
    const transferAmount = Math.floor(rawDamage / 2);
    args.output.damage = Math.max(0, args.output.damage - transferAmount);
    const lvl = thisEffect.getFlag('xjzl-system', 'yihuaLevel') || 1;
    const isMastery = lvl >= 4;
    const targetText = isMastery ? '<b>由你指定的</b> 一名敌方' : '<b>随机的</b> 一名敌方';
    ChatMessage.create({
        content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="border-left: 3px solid #e91e63; padding: 4px; background: rgba(233, 30, 99, 0.05);"><div style="font-weight:bold; color:#e91e63;"><i class="fas fa-sync-alt"></i> 移花接木</div><div>减免了 <b>${transferAmount}</b> 点伤害。</div><div style="font-size:0.85em; margin-top:3px;">请让 20米 内 ${targetText} 承担 <b>${transferAmount}</b> 点气血流失！</div></div></div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

const lvl = Math.max(1, move.computedLevel || 1);
const count = 1 + (lvl - 1);
ui.notifications.info(`请手动移除自身 ${count} 个状态，并击退周围敌人。`);

if (args.isHit && !args.target.system.martial.stanceActive) {
    ui.notifications.info(`${args.target.name} 被击飞 1 米。`);
}

if (!Macros.checkStance(actor, args)) return;

const lvl = Math.max(1, thisItem.system.moves.find(m => m.id === actor.system.martial.stance)?.computedLevel || 1);
const rounds = 1 + (lvl - 1);

const effData = thisItem.effects.getName("素月").toObject();
delete effData._id;
effData.origin = thisItem.uuid;
effData.duration = { rounds: rounds };
await game.xjzl.api.effects.addEffect(actor, effData);

const targets = Array.from(game.user.targets);
if (targets.length === 1) {
    const t = targets[0].actor;
    if (t && t.effects.some(e => e.getFlag("xjzl-system", "slug") === "prone")) {
        const lvl = Math.max(1, args.move.computedLevel || 1);
        args.flags.bonusFeint += lvl;
        const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #3498db; background: rgba(52, 152, 219, 0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#2980b9;"><i class="fas fa-arrow-up"></i> 菊园忆晓</div><div style="font-size:0.9em; color:#555; margin-top:2px;">目标处于倒地状态，虚招值 <span style="color:#2980b9; font-weight:bold;">+${lvl}</span> ！</div></div></div>`;
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    }
}

if (args.isBroken) {
    const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #e67e22; background: rgba(230, 126, 34, 0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#d35400;"><i class="fas fa-shoe-prints"></i> 击破破绽</div><div style="font-size:0.9em; color:#555; margin-top:2px;">成功击破架招！你可以朝任意方向移动 <span style="font-weight:bold;">5 米</span>。</div></div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

const rootEff = CONFIG.statusEffects.find(e => e.id === "root");
if (rootEff) {
    const data = foundry.utils.deepClone(rootEff);
    data.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, data);
}

const hasSuyue = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_suyue");
if (hasSuyue) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const huti = 10 + (lvl - 1) * 20;
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="font-weight:bold; color:#2196f3;">素月分辉 - 护体</div>
            <div>请为范围内友方手动添加 <b>${huti}</b> 点护体真气。</div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const eff = CONFIG.statusEffects.find(e => e.id === "unstable");
    if (eff) {
        const data = foundry.utils.deepClone(eff);
        data.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, data);
    }
}

const effData = thisItem.effects.getName("如意").toObject();
delete effData._id;
effData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(args.target, effData);

const lvl = Math.max(1, move.computedLevel || 1);
const dist = 2 + (lvl - 1) * 2;
await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: "dingli",
    dc: 15,
    label: "抵抗铃音",
    onFail: {
        name: "心神恍惚",
        description: `受控移动 ${dist} 米`,
        icon: "icons/svg/daze.svg",
        duration: { turns: 1 }
    }
});

if (args.isHit) {
    const effData = thisItem.effects.getName("缚铃").toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, effData);
}

const bei = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_bei");
if (bei) {
    const stacks = bei.getFlag("xjzl-system", "stacks") || 1;
    const moran = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_moran");
    const perStack = moran ? 10 : 5;
    const bonus = stacks * perStack;
    args.output.damage += bonus;
    args.output.bonusDesc.push(`悲(${stacks}) 加成 +${bonus}`);
}

if (args.isHit && args.target.system.martial?.stanceActive) {
    const moran = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_moran");
    if (moran) {
        const rage = actor.system.resources.rage.value;
        if (rage < actor.system.resources.rage.max && !actor.xjzlStatuses?.noRecoverRage) {
            await actor.update({ "system.resources.rage.value": rage + 1 });
            const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #e74c3c; background: rgba(231, 76, 60, 0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#c0392b;"><i class="fas fa-fire"></i> 默然之意</div><div style="font-size:0.9em; color:#555; margin-top:2px;">击中开启架招的目标，怒气 <span style="color:#c0392b; font-weight:bold;">+1</span> ！</div></div></div>`;
            ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
        }
    }
}

const bei = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_bei");
if (bei) {
    const stacks = bei.getFlag("xjzl-system", "stacks") || 1;
    const moran = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_moran");
    const perStack = moran ? 10 : 5;
    const bonus = stacks * perStack;
    args.output.damage += bonus;
    args.output.bonusDesc.push(`悲(${stacks}) 加成 +${bonus}`);
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, { id: "fengzhao", duration: { rounds: 1 } });
    const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #8e44ad; background: rgba(142, 68, 173, 0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#732d91;"><i class="fas fa-sad-tear"></i> 悲从心中起</div><div style="font-size:0.9em; color:#555; margin-top:2px;">目标陷入 <span style="color:#8e44ad; font-weight:bold;">封招</span> ！</div></div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
} else if (!args.isHit && args.target.system.martial?.stanceActive) {
    const moran = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_moran");
    if (moran) {
        const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #34495e; background: rgba(52, 73, 94, 0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#2c3e50;"><i class="fas fa-shield-alt"></i> 默然之意</div><div style="font-size:0.9em; color:#555; margin-top:2px;">虽然虚招对抗失败，但由于招式形同失败，目标 <span style="color:#c0392b; font-weight:bold;">无法对你释放反击压制</span> ！</div></div></div>`;
